-- primero el del sacerdote: al pasar a la v2 se va el tótem viejo antes de poner el nuevo
local POR_CLASE = {
    PRIEST = { SACERDOTE, TOTEM },
    MAGE = { TOTEM }, WARLOCK = { TOTEM }, DRUID = { TOTEM }, SHAMAN = { TOTEM }, PALADIN = { TOTEM },
}
D.extras = D.extras or {}
for clase, l in pairs(POR_CLASE) do
    D.extras[clase] = D.extras[clase] or {}
    local hay = {}
    for _, x in ipairs(D.extras[clase]) do if x.uid then hay[x.uid] = true end end
    for _, x in ipairs(l) do
        if not hay[x.uid] then table.insert(D.extras[clase], x) end    -- (si algún día va en AurasDatos, no se repite)
    end
end
